mapper.select:

where inv.del_flag = '0'

    and inv.warehouse_id = #{query.warehouseId}


    and w.warehouse_name like concat('%', #{query.warehouseName}, '%')


    and inv.input_id = #{query.inputId}


    and ai.input_name like concat('%', #{query.inputName}, '%')


    and inv.batch_no like concat('%', #{query.batchNo}, '%')


    and inv.stock_status = #{query.stockStatus}


    and inv.current_quantity >= #{query.quantityMin}


    and inv.current_quantity <= #{query.quantityMax}

order by inv.create_time desc

select ai.input_id as inputId, ai.input_name as inputName, ai.sku as inputSku, ai.type as inputType, CASE ai.type WHEN 'pesticide' THEN '农药' WHEN 'fertilizer' THEN '化肥' WHEN 'seed' THEN '种子' ELSE '' END as inputTypeDesc, sum(inv.current_quantity) as totalQuantity, count(distinct inv.batch_no) as batchCount, count(distinct inv.warehouse_id) as warehouseCount from inv_inventory inv left join agri_input ai on inv.input_id = ai.input_id and ai.del_flag = '0' where inv.del_flag = '0' and inv.current_quantity > 0
and inv.warehouse_id = #{warehouseId}
and ai.type = #{inputType}
group by ai.input_id, ai.input_name, ai.sku, ai.type order by totalQuantity desc

select w.warehouse_id as warehouseId, w.warehouse_name as warehouseName, w.warehouse_type as warehouseType, CASE w.warehouse_type WHEN 'normal' THEN '普通仓库' WHEN 'cold' THEN '冷藏仓库' WHEN 'dangerous' THEN '危险品仓库' ELSE '' END as warehouseTypeDesc, w.capacity, w.used_capacity as usedCapacity, (w.capacity - w.used_capacity) as availableCapacity, concat(round(w.used_capacity / w.capacity * 100, 2), '%') as usageRate, count(distinct ai.type) as inputTypeCount, count(distinct inv.batch_no) as batchCount from inv_warehouse w left join inv_inventory inv on w.warehouse_id = inv.warehouse_id and inv.del_flag = '0' and inv.current_quantity > 0 left join agri_input ai on inv.input_id = ai.input_id and ai.del_flag = '0' where w.del_flag = '0'
and w.supplier_id = #{supplierId}
group by w.warehouse_id, w.warehouse_name, w.warehouse_type, w.capacity, w.used_capacity order by w.warehouse_id

select *
from inv_inventory
where input_id = #{inputId}
  and batch_no = #{batchNo}
  and warehouse_id = #{warehouseId}
  and del_flag = '0'
